import * as THREE from 'three';
import RAPIER from '@dimforge/rapier3d-compat';
await RAPIER.init(); // load WASM
const gravity = { x: 0.0, y: -9.81, z: 0.0 };
const world = new RAPIER.World(gravity);
world.step() advances the simulation by a fixed time step (default 1/60 s). Call it once per render frame.

A rigid body is the physical object (with mass, velocity, position). A collider is its shape for collision detection. Bodies can have one or more colliders.
// dynamic box
const bodyDesc = RAPIER.RigidBodyDesc.dynamic().setTranslation(0, 5, 0);
const body = world.createRigidBody(bodyDesc);
const collDesc = RAPIER.ColliderDesc.cuboid(0.5, 0.5, 0.5) // half-extents
.setRestitution(0.6)
.setFriction(0.8)
.setDensity(1.0);
world.createCollider(collDesc, body);
// matching Three.js mesh
const mesh = new THREE.Mesh(
new THREE.BoxGeometry(1, 1, 1),
new THREE.MeshStandardMaterial({ color: 0xff9966 })
);
mesh.castShadow = true;
scene.add(mesh);
// keep the mesh tied to the body
function sync() {
const t = body.translation();
const r = body.rotation();
mesh.position.set(t.x, t.y, t.z);
mesh.quaternion.set(r.x, r.y, r.z, r.w);
}
Body types:
Dynamic — moves with physics.
Fixed (static) — never moves, infinite mass; for floors, walls.
Kinematic position-based — moves by setting position; collides with dynamics; doesn't react to forces. For characters/platforms.
Kinematic velocity-based — moves by setting velocity; same idea as above.
Collider shapes:
Shape · Constructor
Box · cuboid(hx, hy, hz)
Sphere · ball(r)
Capsule · capsule(halfHeight, r)
Cylinder · cylinder(halfHeight, r)
Cone · cone(halfHeight, r)
Trimesh (any 3D mesh) · trimesh(vertices, indices)
Heightfield (terrain) · heightfield(rows, cols, heights, scale)
Convex hull · convexHull(points)
Trick: never use trimesh for dynamic bodies — only for static terrain. For moving objects, use a primitive (box / capsule) or convex hull. Trimesh-trimesh collisions are 10-100× slower than primitive-primitive.

const bodies = []; // { body, mesh } pairs
function spawnCube(x, y, z) {
const body = world.createRigidBody(
RAPIER.RigidBodyDesc.dynamic().setTranslation(x, y, z)
);
world.createCollider(RAPIER.ColliderDesc.cuboid(0.5, 0.5, 0.5), body);
const mesh = new THREE.Mesh(
new THREE.BoxGeometry(1, 1, 1),
new THREE.MeshStandardMaterial({ color: Math.random() * 0xffffff })
);
mesh.castShadow = true;
scene.add(mesh);
bodies.push({ body, mesh });
}
// floor
const floorBody = world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
world.createCollider(RAPIER.ColliderDesc.cuboid(10, 0.1, 10), floorBody);
const floorMesh = new THREE.Mesh(
new THREE.BoxGeometry(20, 0.2, 20),
new THREE.MeshStandardMaterial({ color: 0x888888 })
);
floorMesh.position.y = -0.1;
floorMesh.receiveShadow = true;
scene.add(floorMesh);
// drop some cubes
for (let i = 0; i < 20; i++) spawnCube(Math.random() * 4 - 2, 5 + i * 1.5, Math.random() * 4 - 2);
renderer.setAnimationLoop(() => {
world.step();
for (const { body, mesh } of bodies) {
const t = body.translation();
const r = body.rotation();
mesh.position.set(t.x, t.y, t.z);
mesh.quaternion.set(r.x, r.y, r.z, r.w);
}
renderer.render(scene, camera);
});
That is the canonical loop. 20 cubes raining onto a floor — pure Rapier + pure Three.js, no helper library.

Variable timestep introduces jitter. The robust pattern:
const FIXED_DT = 1 / 60;
let accumulator = 0;
renderer.setAnimationLoop(() => {
const dt = Math.min(clock.getDelta(), 0.1); // clamp huge jumps
accumulator += dt;
while (accumulator >= FIXED_DT) {
world.step();
accumulator -= FIXED_DT;
}
// render with the bodies' current positions
for (const { body, mesh } of bodies) { /* sync as above */ }
renderer.render(scene, camera);
});
For perfect smoothness, also interpolate between the previous and current physics state proportional to accumulator / FIXED_DT. Most games skip that and look fine.

body.applyImpulse({ x: 0, y: 5, z: 0 }, true); // sudden push (jump)
body.applyTorqueImpulse({ x: 0, y: 1, z: 0 }, true);
body.setLinvel({ x: 2, y: 0, z: 0 }, true); // set velocity directly
body.setAngvel({ x: 0, y: 5, z: 0 }, true);
body.lockTranslations(true, true); // freeze position
body.lockRotations(true, true); // freeze rotation
Joints connect bodies:
Joint · What
Fixed · rigidly attached
Revolute · hinge (one axis rotation)
Prismatic · slider (one axis translation)
Spherical · ball joint (3-axis rotation)
Generic · configurable
const joint = world.createImpulseJoint(
RAPIER.JointData.revolute(
/* anchor1 */ { x: 0, y: 0, z: 0 },
/* anchor2 */ { x: 0, y: 0, z: 0 },
/* axis */ { x: 0, y: 1, z: 0 }
),
bodyA, bodyB, /* wakeUp */ true
);
Joints enable: doors, hinges, ragdoll characters, vehicles (4 prismatic wheel joints), chains, ropes (sequential spherical joints).

For an FPS / third-person character, dynamic body + capsule collider is technically correct but feels squishy. The standard pattern: kinematic character controller that you move manually and Rapier resolves against the world.
const characterController = world.createCharacterController(0.01); // offset
characterController.enableAutostep(0.3, 0.1, true); // stair-step
characterController.enableSnapToGround(0.5); // stick to slopes
const playerBody = world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(0, 1, 0));
const playerCollider = world.createCollider(RAPIER.ColliderDesc.capsule(0.5, 0.3), playerBody);
// per frame, given a desired movement vector
characterController.computeColliderMovement(playerCollider, desiredVec);
const correctedMove = characterController.computedMovement();
const pos = playerBody.translation();
playerBody.setNextKinematicTranslation({
x: pos.x + correctedMove.x,
y: pos.y + correctedMove.y,
z: pos.z + correctedMove.z,
});
Combine with PointerLockControls for mouse-look + WASD inputs. Real character controllers usually add: jump (vertical impulse on grounded check), gravity (manual vy -= 9.81 * dt), and ground-test raycasts.

The pattern from Post 02, complete recipe:
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
renderer.domElement.addEventListener('pointermove', (e) => {
const rect = renderer.domElement.getBoundingClientRect();
pointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
pointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
});
renderer.domElement.addEventListener('click', () => {
raycaster.setFromCamera(pointer, camera);
const hits = raycaster.intersectObjects(scene.children, true);
if (hits.length) {
const { object, point, distance } = hits[0];
console.log('clicked', object.name, 'at', point);
}
});

For scenes with > 10k triangles in raycastable meshes:
npm install three-mesh-bvh
import { acceleratedRaycast, computeBoundsTree, disposeBoundsTree } from 'three-mesh-bvh';
THREE.BufferGeometry.prototype.computeBoundsTree = computeBoundsTree;
THREE.BufferGeometry.prototype.disposeBoundsTree = disposeBoundsTree;
THREE.Mesh.prototype.raycast = acceleratedRaycast;
// then for each raycastable mesh:
mesh.geometry.computeBoundsTree();
Speeds raycasts up to 100× by building a BVH once per geometry. Same library accelerates physics queries when used with custom shapes.

Independent from Three.js raycaster, for collision-based queries (line of sight, projectile trace):
const ray = new RAPIER.Ray(
{ x: origin.x, y: origin.y, z: origin.z },
{ x: dir.x, y: dir.y, z: dir.z }
);
const hit = world.castRay(ray, /* maxToi */ 100, /* solid */ true);
if (hit) {
const point = ray.pointAt(hit.toi);
console.log('hit collider', hit.collider, 'at', point);
}

Editor-style click-and-drag to translate/rotate/scale a mesh:
import { TransformControls } from 'three/addons/controls/TransformControls.js';
const transform = new TransformControls(camera, renderer.domElement);
transform.attach(mesh);
scene.add(transform.getHelper()); // r170+; older versions use `scene.add(transform)`
// disable orbit while transforming
transform.addEventListener('dragging-changed', (e) => {
orbitControls.enabled = !e.value;
});
// switch modes
window.addEventListener('keydown', (e) => {
if (e.key === 'g') transform.setMode('translate');
if (e.key === 'r') transform.setMode('rotate');
if (e.key === 's') transform.setMode('scale');
});
Useful in level editors, scene composition tools, and design viewers.

Click-drag objects across a plane (no rotation/scale):
import { DragControls } from 'three/addons/controls/DragControls.js';
const drag = new DragControls([sphere1, sphere2, sphere3], camera, renderer.domElement);
drag.addEventListener('dragstart', () => orbit.enabled = false);
drag.addEventListener('dragend', () => orbit.enabled = true);
Cheap interactions for prototypes and UI demos.
